const stdout = $input.first().json.stdout || '';

const files = stdout
  .split(/\r?\n/)
  .map(file => file.trim())
  .filter(Boolean);

return files.map(file => ({
  json: {
    path: file,
    source_path: file,
    extension: file.toLowerCase().split('.').pop(),
    file_name: file.split('/').pop()
  }
}));

const input = $input.all();
const output = [];

function addDocument(data) {
  if (!data.content || !String(data.content).trim()) {
    return;
  }

  output.push({
    json: {
      id: data.id || `document-${output.length + 1}`,
      topic: data.topic || 'Software Engineering Reference',
      content: String(data.content),

      source: data.source || 'Knowledge Base',
      document_type: data.document_type || 'reference',
      language: data.language || 'general',
      domain: data.domain || 'software-engineering',

      category: data.category || '',
      rule: data.rule || '',
      related_sonar_rules: data.related_sonar_rules || [],
      severity: data.severity || [],
      issue_type: data.issue_type || [],
      keywords: data.keywords || [],

      file_path: data.file_path || '',
      line: data.line || ''
    }
  });
}

function getText(json) {
  const values = [
    json.text,
    json.content,
    json.extractedText,
    json.extracted_text,
    json.data
  ];

  for (const value of values) {
    if (typeof value === 'string' && value.trim()) {
      return value;
    }
  }

  return '';
}

function getFileName(item) {
  const json = item.json || {};
  const binary = item.binary?.data || {};

  return (
    json.file_name ||
    json.fileName ||
    json.source_path?.split('/').pop() ||
    json.path?.split('/').pop() ||
    binary.fileName ||
    ''
  ).toLowerCase();
}

function parseJsonLines(text) {
  return String(text)
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(Boolean)
    .map(line => {
      try {
        return JSON.parse(line);
      } catch {
        return null;
      }
    })
    .filter(Boolean);
}

for (const item of input) {
  const json = item.json || {};
  const fileName = getFileName(item);
  const text = getText(json);

  /*
   * 1. sonarqube_rule_metadata.json
   *
   * Deteksi berdasarkan struktur JSON, bukan nama file.
   */
  const rules =
    Array.isArray(json.rules)
      ? json.rules
      : Array.isArray(json.data?.rules)
        ? json.data.rules
        : null;

  if (rules) {
    for (const rule of rules) {
      const severity = Object.keys(rule.severity_counts || {});
      const issueType = Object.keys(rule.type_counts || {});

      const content = [
        `SonarQube rule: ${rule.rule || ''}`,
        `Category: ${rule.category || ''}`,
        `Description: ${rule.description || ''}`,
        `Remediation: ${rule.remediation || ''}`,
        `Occurrences: ${rule.occurrences || 0}`,
        `Severity: ${severity.join(', ')}`,
        `Issue type: ${issueType.join(', ')}`,
        `Keywords: ${(rule.keywords || []).join(', ')}`,
        `Recommended sources: ${(rule.recommended_sources || []).join(', ')}`
      ].join('\n');

      addDocument({
        id: `rule-${String(rule.rule || output.length)
          .replace(/[^a-zA-Z0-9]+/g, '-')}`,

        topic: `${rule.rule || 'SonarQube Rule'} - ${rule.category || ''}`,
        content,

        source: 'SonarQube Rule Metadata',
        document_type: 'rule-guidance',
        language: rule.language || 'typescript',
        domain: 'static-analysis',

        category: rule.category || '',
        rule: rule.rule || '',
        related_sonar_rules: rule.rule ? [rule.rule] : [],
        severity,
        issue_type: issueType,
        keywords: rule.keywords || []
      });
    }

    continue;
  }

  /*
   * 2. JSONL SonarQube issue metadata
   *
   * Deteksi dari isi teks.
   */
  if (
    fileName.endsWith('.jsonl') ||
    (
      text &&
      text.trim().startsWith('{') &&
      text.includes('"issue_id"') &&
      text.includes('"rule"')
    )
  ) {
    const records = parseJsonLines(text);

    if (records.length > 0) {
      for (const issue of records) {
        if (!issue.rule && !issue.message) {
          continue;
        }

        const content = [
          `SonarQube issue: ${issue.issue_id || ''}`,
          `Rule: ${issue.rule || ''}`,
          `File: ${issue.file_path || ''}`,
          `Severity: ${issue.severity || ''}`,
          `Type: ${issue.type || ''}`,
          `Message: ${issue.message || ''}`,
          `Line: ${issue.line || ''}`,
          `Category: ${issue.category || ''}`,
          `Keywords: ${(issue.keywords || []).join(', ')}`,
          `Recommended sources: ${(issue.recommended_sources || []).join(', ')}`
        ].join('\n');

        addDocument({
          id: issue.issue_id || `issue-${output.length + 1}`,
          topic: `${issue.rule || 'SonarQube Issue'} - ${issue.category || ''}`,
          content,

          source: 'SonarQube Issue Metadata',
          document_type: 'sonarqube-issue',
          language: 'typescript',
          domain: 'static-analysis',

          category: issue.category || '',
          rule: issue.rule || '',
          related_sonar_rules: issue.rule ? [issue.rule] : [],
          severity: issue.severity ? [issue.severity] : [],
          issue_type: issue.type ? [issue.type] : [],
          keywords: issue.keywords || [],
          file_path: issue.file_path || '',
          line: issue.line || ''
        });
      }

      continue;
    }
  }

  /*
   * 3. Dokumen PDF atau Markdown
   *
   * Jika nama file hilang, teks biasa tetap diproses sebagai dokumen.
   */
  if (text.trim()) {
    let source = 'Knowledge Base Reference';
    let documentType = 'reference';

    if (fileName.includes('clean')) {
      source = 'Clean Code';
      documentType = 'book';
    } else if (fileName.includes('pressman')) {
      source = 'Software Engineering';
      documentType = 'book';
    } else if (fileName.includes('solid')) {
      source = 'SOLID Design Principles';
      documentType = 'article';
    } else if (fileName.includes('refactoring')) {
      source = 'Refactoring Cheat Sheet';
      documentType = 'refactoring-reference';
    } else if (fileName.endsWith('.pdf')) {
      source = 'PDF Reference';
      documentType = 'pdf-reference';
    } else if (fileName.endsWith('.md')) {
      source = 'Markdown Reference';
      documentType = 'markdown-reference';
    }

    addDocument({
      id: `doc-${source.toLowerCase().replace(/[^a-z0-9]+/g, '-')}-${output.length + 1}`,
      topic: source,
      content: text,

      source,
      document_type: documentType,
      language: 'general',
      domain: 'software-engineering',

      category: 'software engineering',
      related_sonar_rules: [],
      severity: [],
      issue_type: [],
      keywords: [
        'software engineering',
        'software quality',
        'clean code',
        'maintainability'
      ]
    });

    continue;
  }

  /*
   * 4. Diagnostic apabila item tetap tidak memiliki teks
   */
  const availableFields = Object.keys(json);

  if (availableFields.length > 0) {
    output.push({
      json: {
        id: `diagnostic-${output.length + 1}`,
        topic: 'Extraction Diagnostic',
        content: `Tidak menemukan teks. Field yang tersedia: ${availableFields.join(', ')}`,
        source: 'Workflow Diagnostic',
        document_type: 'diagnostic',
        language: 'general',
        domain: 'debugging',
        category: 'diagnostic',
        related_sonar_rules: [],
        severity: [],
        issue_type: [],
        keywords: availableFields
      }
    });
  }
}

return output;
